#include <cassert>
#include <iostream>
#include <string>
#include <vector>
#ifdef NDEBUG
#error Tests require assertions enabled
#endif
struct Item { std::string id; int depth; };
// 한 루트, 깊이 최대8. 형제는 허용하지만 부모 없는 깊이 도약은 거부.
bool valid(const std::vector<Item>& items) {
    if(items.empty() || items[0].depth!=0) return false;
    for(std::size_t i=0;i<items.size();++i) {
        if(items[i].id.empty() || items[i].depth<0 || items[i].depth>8) return false;
        if(i && (items[i].depth==0 || items[i].depth>items[i-1].depth+1)) return false;
        for(std::size_t k=0;k<i;++k) if(items[k].id==items[i].id) return false;
    }
    return true;
}
int main(){
    assert(valid({{"goal",0},{"rule",1},{"cost",2},{"test",1}}));
    assert(!valid({}));
    assert(!valid({{"goal",0},{"gap",2}}));
    assert(!valid({{"goal",0},{"second-root",0}}));
    assert(!valid({{"goal",0},{"goal",1}}));
    assert(!valid({{"goal",0},{"",1}}));
    assert(!valid({{"goal",0},{"negative",-1}}));
    std::vector<Item> chain;
    for(int i=0;i<=8;++i)chain.push_back({std::to_string(i),i});
    assert(valid(chain));chain.push_back({"9",9});assert(!valid(chain));
    std::cout<<"outline structure tests passed\n";
}
